<?php
namespace MarineVideoPortal\Models;
use MarineVideoPortal\Core\Database;
class Video{public static function all($s='',$c=null,$l=50,$o=0){$sql="SELECT vm.*, co.name as collection_name FROM videos_meta vm LEFT JOIN collections co ON vm.collection_id=co.id WHERE 1=1";$p=[];if($s){$sql.=" AND vm.title LIKE ?";$p[]="%$s%";}if($c){$sql.=" AND vm.collection_id=?";$p[]=$c;}$sql.=" ORDER BY vm.custom_order ASC, vm.created_at DESC LIMIT $l OFFSET $o";return Database::fetchAll($sql,$p);}public static function count($s='',$c=null){$sql="SELECT COUNT(*) as cnt FROM videos_meta vm WHERE 1=1";$p=[];if($s){$sql.=" AND title LIKE ?";$p[]="%$s%";}if($c){$sql.=" AND collection_id=?";$p[]=$c;}$r=Database::fetchOne($sql,$p);return (int)($r['cnt']??0);}public static function find($g){return Database::fetchOne("SELECT * FROM videos_meta WHERE guid=?",[$g]);}public static function updateMeta($g,$d){$f=[];$p=[];foreach(['title','custom_order'] as $k){if(isset($d[$k])){$f[]="$k=?";$p[]=$d[$k];}}if(!$f)return;$p[]=$g;Database::exec("UPDATE videos_meta SET ".implode(',',$f)." WHERE guid=?",$p);}public static function deleteMeta($g){Database::exec("DELETE FROM videos_meta WHERE guid=?",[$g]);}}
